/// <summary>
/// Business event triggered when a general journal is posted.
/// </summary>
[BusinessEvents(classStr(AAXGeneralJournalPostedBusinessEventContract), 'GeneralJournalPostedBusinessEventName', 'GeneralJournalPostedBusinessEventDescription', ModuleAxapta::Ledger)]
public final class AAXGeneralJournalPostedBusinessEvent extends BusinessEventsBase
{
    private LedgerJournalTable ledgerJournalTable;

}

Method.Source:
/// <summary>
/// Gets or sets the source LedgerJournalTable for building the event contract.
/// </summary>
private LedgerJournalTable parmLedgerJournalTable(LedgerJournalTable _ledgerJournalTable = ledgerJournalTable)
{
    ledgerJournalTable = _ledgerJournalTable;

    return ledgerJournalTable;
}

/// <summary>
/// Creates a new <c>AAXGeneralJournalPostedBusinessEvent</c> instance from the specified <c>LedgerJournalTable</c> record.
/// </summary>
/// <param name="_ledgerJournalTable">The source LedgerJournalTable record.</param>
/// <returns>A new instance of <c>AAXGeneralJournalPostedBusinessEvent</c>.</returns>
public static AAXGeneralJournalPostedBusinessEvent newFromLedgerJournalTable(LedgerJournalTable _ledgerJournalTable)
{
    AAXGeneralJournalPostedBusinessEvent businessEvent = new AAXGeneralJournalPostedBusinessEvent();
    businessEvent.parmLedgerJournalTable(_ledgerJournalTable);

    return businessEvent;
}

/// <summary>
/// Private constructor. Use static factory methods to create instances.
/// </summary>
private void new()
{
}

/// <summary>
/// Builds the data contract for this business event.
/// </summary>
/// <returns>The populated <c>AAXGeneralJournalPostedBusinessEventContract</c>.</returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return AAXGeneralJournalPostedBusinessEventContract::newFromLedgerJournalTable(ledgerJournalTable);
}
